    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a1-voicemail-birthday-party","title":"An Invitation to a Birthday Party","level":"A1","status":"published","sort_order":200,"metadata":{},"summary":"Malika leaves a voicemail to invite Aziz to her birthday party on Saturday.","transcript_text":"Hi Aziz, it's Malika. It's my birthday on Saturday. I'm having a small party at my flat. It starts at six o'clock in the evening. My mother is making plov, and my sister is making a big cake. Please don't bring a present. Just bring your guitar! My flat is near Chilonzor metro station. Call me or send me a message. See you on Saturday!","category":"Daily Life","accent":"general","speed_label":"slow","speed_wpm":110,"duration_seconds":35,"audio_url":null,"focus_skill":"detail","tags":["voicemail","birthday","friends"],"questions":[{"id":"q1","type":"mcq","prompt":"When is the party?","options":["On Friday","On Saturday","On Sunday","On Monday"],"answer_index":1,"explanation":"Malika says: \"It's my birthday on Saturday.\""},{"id":"q2","type":"mcq","prompt":"What time does the party start?","options":["At five o'clock","At six o'clock","At seven o'clock","At eight o'clock"],"answer_index":1,"explanation":"\"It starts at six o'clock in the evening.\""},{"id":"q3","type":"mcq","prompt":"Who is making the cake?","options":["Malika","Malika's mother","Malika's sister","Aziz"],"answer_index":2,"explanation":"\"My sister is making a big cake.\" Her mother is making plov."},{"id":"q4","type":"mcq","prompt":"What does Malika want Aziz to bring?","options":["A present","A cake","His guitar","Some plov"],"answer_index":2,"explanation":"She says: \"Please don't bring a present. Just bring your guitar!\""}]}$seed$::jsonb) r
