    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"a2-hotel-booking-voicemail","title":"A Message From the Hotel","level":"A2","status":"published","sort_order":200,"metadata":{},"summary":"A hotel receptionist in Istanbul calls to confirm a booking and explain arrival details.","transcript_text":"Good afternoon, this is a message for Mr Timur Rakhimov. My name is Sara, and I'm calling from the Blue Garden Hotel in Istanbul. Thank you for your booking. You have a double room for three nights, from the twelfth to the fifteenth of May. Your room will be ready at two o'clock in the afternoon. If you arrive earlier, you can leave your bags at the reception desk. Breakfast is included, and we serve it from seven to ten in the morning. You asked about getting here from the airport. There is a bus every thirty minutes, and it stops just in front of the hotel. A taxi is faster, but it is more expensive. If you have any questions, please call us back or send us an email. We look forward to seeing you, and have a good trip!","category":"Travel","accent":"general","speed_label":"slow","speed_wpm":125,"duration_seconds":68,"audio_url":null,"focus_skill":"detail","tags":["voicemail","hotel","travel"],"questions":[{"id":"q1","type":"mcq","prompt":"How many nights is Timur's booking for?","options":["Two","Three","Four","Fifteen"],"answer_index":1,"explanation":"\"You have a double room for three nights, from the twelfth to the fifteenth of May.\""},{"id":"q2","type":"mcq","prompt":"What can Timur do if he arrives before two o'clock?","options":["Go to his room","Have a free lunch","Leave his bags at reception","Change his room"],"answer_index":2,"explanation":"\"If you arrive earlier, you can leave your bags at the reception desk.\""},{"id":"q3","type":"mcq","prompt":"What does Sara say about breakfast?","options":["It is not included.","It is included and served from seven to ten.","It is served until noon.","It costs extra on Sundays."],"answer_index":1