    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"b1-mahalla-hashar-saturday","title":"A Hashar in Our Mahalla","level":"B1","status":"published","sort_order":200,"metadata":{},"summary":"At a neighbourhood meeting, a volunteer explains the plan for Saturday's community clean-up and tree planting.","transcript_text":"Good evening, neighbours, and thank you for coming to this meeting. As you know, spring is here, and our mahalla is organising a hashar this Saturday. For anyone who is new to the area, a hashar is when neighbours work together to help the community. This time we're planning to clean the park next to the school and plant fifty young trees. We'll meet at the park gate at eight in the morning, before it gets too hot. Please wear old clothes and bring gloves if you have them. The mahalla will provide spades, rubbish bags and drinking water. We especially need a few people with cars to collect the trees from the garden centre on Friday evening. If you can help with that, please speak to me after the meeting. Children are very welcome, but they should stay with an adult. When we've finished, at about one o'clock, there will be lunch for everyone in the school yard. I hope to see as many of you there as possible.","category":"Community","accent":"general","speed_label":"natural","speed_wpm":140,"duration_seconds":73,"audio_url":null,"focus_skill":"detail","tags":["mahalla","hashar","community","volunteering"],"questions":[{"id":"q1","type":"mcq","prompt":"What is a hashar, according to the speaker?","options":["A spring festival with music","When neighbours work together to help the community","A meeting of the mahalla committee","A competition between schools"],"answer_index":1,"explanation":"\"A hashar is when neighbours work together to help the community.\""},{"id":"q2","type":"mcq","prompt":"Why will they meet at eight in the morning?","options":["The park opens at eight.","The trees arrive at eight.","It is before it gets too hot.","The school starts later."],"answer_index":2,"explanation":"\"We'll meet at the park gate at eight in the morning, before it gets too hot.\""},{"id":"q3","type":"mcq","prompt":"What should volunteers bring themselves?","options":["Spades","Gloves, if they have them","Rubbish bags","Young trees"],"answer_index":1,"explanation":"\"Please wear old clothes and bring gloves if you have them.\" The mahalla provides spades, bags and water."},{"id":"q4","type":"mcq","prompt":"What help does the speaker especially need?","options":["People to cook lunch","People to look after the children","People with cars to collect the trees on Friday","People to clean the school"],"answer_index":2,"explanation":"\"We especially need a few people with cars to collect the trees from the garden centre on Friday evening.\""}]}$seed$::jsonb) r
