  if exists (select 1 from public.listening_items where product_id = v_product_listening and language_id = v_en_id and slug = 'c2-lecture-memory-reconstruction') then
    raise notice 'skipped existing listening item %', 'c2-lecture-memory-reconstruction';
  else
    insert into public.listening_items (slug, title, level, status, sort_order, metadata, summary, transcript_text, category, accent, speed_label, speed_wpm, duration_seconds, audio_url, focus_skill, tags, questions, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.summary, r.transcript_text, r.category, r.accent, r.speed_label, r.speed_wpm, r.duration_seconds, r.audio_url, r.focus_skill, r.tags, r.questions, v_product_listening, v_en_id
    from jsonb_populate_record(null::public.listening_items, $seed${"slug":"c2-lecture-memory-reconstruction","title":"Lecture: Memory Is Not a Recording","level":"C2","status":"published","sort_order":200,"metadata":{},"summary":"A psychology lecture on why remembering is an act of reconstruction rather than playback, drawing on Bartlett's classic study.","transcript_text":"Let me begin with a claim that most of you will instinctively resist: your memories are not recordings. We tend to imagine remembering as a kind of playback, as if the past were stored somewhere intact, merely waiting to be retrieved. The evidence suggests something rather less flattering. In the early nineteen-thirties, the British psychologist Frederic Bartlett asked volunteers to read an unfamiliar folk tale and then reproduce it from memory, sometimes repeatedly over weeks and months. What he found was not simply that details went missing. Rather, the story was quietly reshaped: elements that seemed strange to the readers were dropped or rationalised, and the narrative drifted towards what they already found familiar. Bartlett concluded that remembering is an act of reconstruction, guided by what he called schemas, the frameworks of expectation we bring to any experience. Crucially, the people in his study did not experience their versions as inventions. As far as they were concerned, they were simply recalling what they had read. This is the uncomfortable part. Confidence, it turns out, is a poor guide to accuracy: a memory can feel vivid and certain and still be substantially wrong. The implications extend well beyond the laboratory, to courtrooms, to job interviews, and to every family argument about who said what. None of this means that memory is worthless. It means that memory is built for usefulness, not fidelity, and we would do well to hold even our most cherished recollections a little more lightly.","category":"Science","accent":"general","speed_label":"fast","speed_wpm":170,"duration_seconds":87,"audio_url":null,"focus_skill":"inference","tags":["lecture","psychology","memory"],"questions":[{"id":"q1","type":"mcq","prompt":"Which common belief does the lecturer set out to challenge?","options":["That memory gets worse with age","That memories are stored intact and simply played back","That stories are easier to remember than facts","That confidence improves memory"],"answer_index":1,"explanation":"We imagine remembering \"as a kind of playback, as if the past were stored somewhere intact\"; the lecturer argues this is wrong."},{"id":"q2","type":"mcq","prompt":"What did Bartlett's study show, beyond the loss of details?","options":["Participants added completely new characters to the story.","The story was reshaped towards what the readers found familiar.","Repeating the story made it more accurate.","Participants remembered strange details best."],"answer_index":1,"explanation":"Strange elements \"were dropped or rationalised, and the narrative drifted towards what they already found familiar\"."},{"id":"q3","type":"mcq","prompt":"In the lecture, what are schemas?","options":["Notes participants made while reading","Errors that appear in repeated retellings","The frameworks of expectation we bring to experience","Techniques for improving recall"],"answer_index":2,"explanation":"Bartlett's schemas are \"the frameworks of expectation we bring to any experience\"."},{"id":"q4","type":"mcq","prompt":"Why does the lecturer call one finding \"the uncomfortable part\"?","options":["Because the participants knew they were inventing details","Because distorted memories can feel just as genuine and certain as accurate ones","Because the study was carried out unfairly","Because the folk tale was frightening"],"answer_index":1,"explanation":"The participants did not see their versions as inventions, and \"a memory can feel vivid and certain and still be substantially wrong\"."},{"id":"q5","type":"mcq","prompt":"What is the lecturer's overall conclusion?","options":["Memory is too unreliable to be useful.","Only recorded evidence should be trusted.","Memory serves us well but is not built for exact accuracy, so we should hold it lightly.","Training can make memory as reliable as a recording."],"answer_index":2,"explanation":"\"None of this means that memory is worthless. It means that memory is built for usefulness, not fidelity.\""}]}$seed$::jsonb) r
