    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a1-prepositions-of-place","title":"In, on, under, next to: where things are","level":"A1","status":"published","sort_order":200,"metadata":{},"focus_area":"prepositions","explanation_text":"Use a preposition to say where something is. in = inside something: in the bag, in the room, in Tashkent. on = on top of something or touching a surface: on the table, on the wall, on the second floor. under = below something: under the bed. next to = at the side of something, very near: next to the window. between = with one thing on each side: between the bank and the café. Use at for a place where you do something: at home, at school, at work, at the bus stop.","contrast_text":"Compare: The keys are on the desk (on top of it). The keys are in the desk (inside a drawer). The cat is under the desk (below it).","common_error_pattern":"Using in for every place, leaving out to after next, or saying 'in home' instead of 'at home'.","examples_json":[{"bad":"My phone is in the table.","good":"My phone is on the table."},{"bad":"She lives on Tashkent.","good":"She lives in Tashkent."},{"bad":"I am in home now.","good":"I am at home now."},{"bad":"The bank is next the park.","good":"The bank is next to the park."}],"tags":["prepositions","place"]}$seed$::jsonb) r
