    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a1-present-continuous-now","title":"Present continuous: what is happening now","level":"A1","status":"published","sort_order":200,"metadata":{},"focus_area":"present-continuous","explanation_text":"Use am, is or are + verb-ing for actions that are happening now, at the moment you speak: I am reading. She is cooking. They are playing football. Negatives: I'm not working. He isn't sleeping. They aren't listening. Questions: Are you listening? Is it raining? Spelling: most verbs add -ing (read → reading). If the verb ends in -e, drop the -e (make → making). Short verbs like sit, run and swim double the last letter (sitting, running, swimming).","contrast_text":"Compare: I drink tea every morning (a habit, present simple). I am drinking tea now (at this moment, present continuous).","common_error_pattern":"Leaving out am, is or are ('She cooking'), or forgetting -ing after am, is or are ('I am read').","examples_json":[{"bad":"She cooking dinner now.","good":"She is cooking dinner now."},{"bad":"They are play football in the park.","good":"They are playing football in the park."},{"bad":"Look! It snowing.","good":"Look! It's snowing."},{"bad":"I am siting on the bus.","good":"I am sitting on the bus."}],"tags":["present continuous","now"]}$seed$::jsonb) r
