    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a2-prepositions-of-time","title":"In, on, at for time","level":"A2","status":"published","sort_order":200,"metadata":{},"focus_area":"prepositions","explanation_text":"Use at for clock times and a few fixed phrases: at 7 o'clock, at noon, at night, at the weekend (British English). Use on for days and dates: on Monday, on 21 March, on my birthday, on Friday morning. Use in for longer periods: in the morning, in July, in winter, in 2010. Don't use in, on or at before this, next, last, every, today, tomorrow or yesterday: I saw her last Monday. We're leaving next week.","contrast_text":"Compare: in the morning, but on Monday morning. at night, but in the evening.","common_error_pattern":"Using in with days and dates ('in Monday'), or putting a preposition before next, last or every ('on next week').","examples_json":[{"bad":"The lesson starts in 9 o'clock.","good":"The lesson starts at 9 o'clock."},{"bad":"We celebrate Navruz in 21 March.","good":"We celebrate Navruz on 21 March."},{"bad":"My birthday is on July.","good":"My birthday is in July."},{"bad":"I'll call you on next Friday.","good":"I'll call you next Friday."}],"tags":["prepositions","time"]}$seed$::jsonb) r
