    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"a2-present-perfect-experience","title":"Present perfect: ever, never and experiences","level":"A2","status":"published","sort_order":200,"metadata":{},"focus_area":"present-perfect","explanation_text":"Use have or has + past participle to talk about experiences in your life up to now, when the exact time is not important: I have visited Bukhara. She has never eaten sushi. Ask with ever: Have you ever flown on a plane? Short answers: Yes, I have. / No, I haven't. Regular past participles end in -ed (visited, worked). Many common verbs are irregular: be → been, see → seen, eat → eaten, ride → ridden, do → done. Use been (not gone) for a place you visited and came back from. If you say when it happened (yesterday, in 2022, last summer), use the past simple: I visited Bukhara last summer.","contrast_text":"Compare: I have been to Samarkand (some time in my life). I went to Samarkand last summer (a finished time).","common_error_pattern":"Using the past simple form after have ('I have saw'), or using the present perfect with a finished time ('I have seen him yesterday').","examples_json":[{"bad":"Have you ever ate kazy?","good":"Have you ever eaten kazy?"},{"bad":"She has never went abroad.","good":"She has never been abroad."},{"bad":"I have seen that film last week.","good":"I saw that film last week."},{"bad":"He never has played tennis.","good":"He has never played tennis."}],"tags":["present perfect","experience"]}$seed$::jsonb) r
