  -- grammar: c1-passive-reporting-structures (C1)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c1-passive-reporting-structures') then
    raise notice 'skipped existing grammar item %', 'c1-passive-reporting-structures';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c1-passive-reporting-structures","title":"It is said that / is thought to have: reporting with the passive","level":"C1","status":"published","sort_order":200,"metadata":{},"focus_area":"passive","explanation_text":"In formal and news writing we often report what people say or believe without saying who they are. We use a reporting verb (say, think, believe, report, expect, know, consider, claim) in the passive, in one of two patterns. 1) It + passive + that-clause: It is believed that the fire started in the kitchen. 2) Subject + passive + to-infinitive: The fire is believed to have started in the kitchen. In pattern 2, choose the infinitive by time: to + verb for the same time or the future (He is said to live in Paris; Prices are expected to rise), to be + -ing for an action in progress (She is thought to be working on a new novel), and to have + past participle for an earlier action (The thieves are reported to have escaped by car). Use to have been + past participle when the earlier action is passive (The bridge is thought to have been built in the 1800s). When the reporting itself is in the past, change only the reporting verb: It was thought that... / He was thought to be...","contrast_text":"Compare: It is reported that the director resigned yesterday. The director is reported to have resigned yesterday. Both are correct; the second puts the person at the start of the sentence.","common_error_pattern":"Using a simple infinitive for an earlier action ('He is said to leave the country last week'), or mixing the two patterns ('He is said that he...').","examples_json":[{"bad":"The fire is thought to start in the kitchen last night.","good":"The fire is thought to have started in the kitchen last night."},{"bad":"He is said that he speaks six languages.","good":"He is said to speak six languages."},{"bad":"The new bridge is expected that it will open in May.","good":"The new bridge is expected to open in May."},{"bad":"It is believed the suspect to be abroad.","good":"The suspect is believed to be abroad."}],"tags":["passive","reporting verbs","formal writing"]}$seed$::jsonb) r
