  -- grammar: c2-inverted-conditionals (C2)
  if exists (select 1 from public.grammar_units where product_id = v_product_grammar and language_id = v_en_id and slug = 'c2-inverted-conditionals') then
    raise notice 'skipped existing grammar item %', 'c2-inverted-conditionals';
  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c2-inverted-conditionals","title":"Had I known, should you need, were it not for","level":"C2","status":"published","sort_order":200,"metadata":{},"focus_area":"inversion","explanation_text":"In formal English, if can be dropped from a conditional and the auxiliary moved in front of the subject. Should + subject + bare infinitive replaces if for possible but unlikely future events, especially in formal letters and instructions: Should you require further information, please contact us. Were + subject + to-infinitive replaces if in hypothetical sentences: Were the university to raise its fees, many students would leave. With be, use were alone: Were I in your position, I would decline the offer. Had + subject + past participle replaces if in third and mixed conditionals: Had we left earlier, we would have caught the train. Were it not for (present) and Had it not been for (past) mean 'without': Were it not for her help, I would be lost. Had it not been for her help, I would have failed. In the negative, not comes after the subject and is never contracted: Had I not seen it (not Hadn't I seen it).","contrast_text":"Compare: If I had known about the strike, I would have taken a taxi. Had I known about the strike, I would have taken a taxi. The meaning is the same; the second is more formal.","common_error_pattern":"Keeping if together with inversion ('If had I known'), contracting the negative ('Hadn't I known'), or adding will after should ('Should you will need').","examples_json":[{"bad":"If had we booked earlier, we would have got a discount.","good":"Had we booked earlier, we would have got a discount."},{"bad":"Hadn't it been for the map, we would have got lost.","good":"Had it not been for the map, we would have got lost."},{"bad":"Should you will need help, call reception.","good":"Should you need help, call reception."},{"bad":"Were the university raise its fees, many students would leave.","good":"Were the university to raise its fees, many students would leave."}],"tags":["inversion","conditionals","formal style"]}$seed$::jsonb) r
