  else
    insert into public.grammar_units (slug, title, level, status, sort_order, metadata, focus_area, explanation_text, contrast_text, common_error_pattern, examples_json, tags, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.focus_area, r.explanation_text, r.contrast_text, r.common_error_pattern, r.examples_json, r.tags, v_product_grammar, v_en_id
    from jsonb_populate_record(null::public.grammar_units, $seed${"slug":"c2-tricky-subject-verb-agreement","title":"Tricky agreement: a number of, neither of, the majority","level":"C2","status":"published","sort_order":200,"metadata":{},"focus_area":"agreement","explanation_text":"In careful writing, the verb agrees with the real head of the subject, not with the nearest noun: The quality of the photos is poor. Phrases such as along with, as well as and together with do not change the subject: The director, as well as her assistants, is attending. A number of + plural noun takes a plural verb (A number of problems have arisen), but the number of takes a singular verb (The number of applicants has doubled). Each, either and neither (of) take a singular verb in formal style: Neither of the reports mentions the cost. Words like majority, half, the rest and fractions agree with the noun after of: Half of the money was stolen; half of the students were absent. An amount seen as one unit takes a singular verb: Ten kilometres is a long way to walk. With either ... or and neither ... nor, the verb agrees with the nearer subject: Neither the manager nor the staff were informed.","contrast_text":"Compare: The number of students in the group is small. A number of students in the group are from abroad.","common_error_pattern":"Making the verb agree with the nearest noun instead of the real subject, e.g. 'The list of requirements are online.'","examples_json":[{"bad":"The list of requirements are on the website.","good":"The list of requirements is on the website."},{"bad":"The number of complaints have risen sharply.","good":"The number of complaints has risen sharply."},{"bad":"Neither of the candidates have any management experience.","good":"Neither of the candidates has any management experience."},{"bad":"Twenty dollars are too much for a cup of coffee.","good":"Twenty dollars is too much for a cup of coffee."}],"tags":["subject-verb agreement","formal writing"]}$seed$::jsonb) r
