    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read your bill","instructions":"Read your mobile statement. Then answer the questions.","prompt_text":"MONTHLY STATEMENT — April\nStandard plan: 90,000 som\nRoaming data (Turkey): 2.1 GB — 186,000 som\nInternational calls: 0 som\nTotal: 276,000 som\nNote: Roaming charges apply when data roaming is switched on in your phone settings. Customers may request a review of any charge within 30 days of the statement date.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What made the bill so high?","options":["International calls","Mobile data used abroad","A new, more expensive plan"],"answer":1,"explanation":"The extra cost is \"Roaming data (Turkey): 2.1 GB — 186,000 som\"."},{"id":"q2","prompt":"What does the note suggest?","options":["Roaming is free for all customers","You can only be charged if data roaming was switched on","Charges cannot be reviewed"],"answer":1,"explanation":"\"Roaming charges apply when data roaming is switched on in your phone settings.\""},{"id":"q3","prompt":"How long do you have to ask for a review?","options":["7 days","30 days from the statement date","Until the next bill"],"answer":1,"explanation":"\"Within 30 days of the statement date.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the call centre","instructions":"You phone the operator. Listen to the agent and answer the questions.","prompt_text":"Thanks for holding. So, I've looked at your account. You're right that data roaming was switched off when you left. But our records show it was switched on again on the fifth of April, probably during an automatic phone update. I'm afraid I can't remove the charge completely, but as this is your first roaming charge, I can offer a fifty per cent goodwill refund today. Alternatively, you can submit a formal complaint in writing, and our billing team will review it within ten working days.","expected_answer_json":{"questions":[{"id":"q1","prompt":"According to the agent, what probably caused the problem?","options":["You changed your plan","An automatic phone update switched roaming on","The network made a billing error"],"answer":1,"explanation":"\"It was switched on again… probably during an automatic phone update.\""},{"id":"q2","prompt":"What are your two options?","options":["A full refund or a new phone","A 50% refund now or a formal written review","A discount next month or a new SIM card"],"answer":1,"explanation":"She offers \"a fifty per cent goodwill refund today\" or \"a formal complaint in writing\"."}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
