    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write a formal complaint","instructions":"You decide not to accept the 50% offer. Write a formal complaint to the billing team: explain the situation, say why you think the charge is unfair, and state the outcome you expect.","prompt_text":"To: Billing Team\nSubject: Request for review — April statement","expected_answer_json":{"goal":"Make a clear, polite case that the charge is unfair and ask for a specific outcome.","points":[{"label":"explain the situation","any":["abroad","holiday","turkey","travel*","switched off","turned off","update"]},{"label":"say why it is unfair","any":["unfair","not aware","unaware","without my","no warning","no notification","no text","no message","didn't","did not"]},{"label":"state the outcome you expect","any":["full refund","refund","remove","cancel","waive","credit","reimburs*"]},{"label":"refer to evidence","any":["attached","screenshot","evidence","records","settings"]}],"model_answer":"Dear Billing Team,\nI am writing to request a review of the roaming data charge of 186,000 som on my April statement. Before travelling to Turkey, I deliberately switched off data roaming. According to your agent, it was switched on again during an automatic phone update, which I was not aware of. I also received no text message warning me that I was paying roaming rates. I therefore consider the charge unfair and ask you to remove it in full. I have attached a screenshot of my settings from before the trip.\nYours faithfully,\nDilnoza Rakhimova"},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
