    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"b2-hosting-guests-in-samarkand","title":"Hosting visiting partners in Samarkand","level":"B2","status":"published","sort_order":200,"metadata":{},"context_text":"Your company in Tashkent is hosting two partners, Lucía and Marco, from a travel company in Spain. You've organised a one-day trip to Samarkand for Thursday, and you are their guide for the day.","objective_text":"Check the programme, adapt it when plans change, confirm the new plan in writing, and welcome the guests on site.","mission_type":"travel","target_vocabulary":["itinerary","madrasa","mausoleum","vegetarian","revised plan"],"target_grammar":"future forms for arrangements and suggestions (We'll take… How about… I've arranged for…)","cultural_note":"Visitors to historic mausoleums in Uzbekistan are usually asked to dress modestly. Hosts often mention it in advance so guests are not caught out.","success_conditions_json":["Understand the programme and the dress code","Identify what has changed and the guests' priorities","Send a revised plan that solves the travel and food problems","Welcome the guests at Registan and outline the day"],"skill_mix":["reading","listening","writing","speaking"]}$seed$::jsonb) r
