    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the programme","instructions":"Read the programme you sent the guests. Then answer the questions.","prompt_text":"Thursday programme\n08:00 Fast train from Tashkent (arrives 10:10)\n10:45 Registan Square, guided visit (90 min)\n12:30 Lunch: plov at a family restaurant\n14:00 Gur-e-Amir Mausoleum\n15:30 Free time at Siab Bazaar\n17:30 Dinner meeting with local tour operators\n20:30 Train back to Tashkent\nPlease note: when visiting mausoleums, wear clothes that cover your shoulders and knees.","expected_answer_json":{"questions":[{"id":"q1","prompt":"How long is the guided visit at Registan?","options":["45 minutes","90 minutes","Two hours"],"answer":1,"explanation":"\"Registan Square, guided visit (90 min)\"."},{"id":"q2","prompt":"What should the guests wear for Gur-e-Amir?","options":["Formal business clothes","Clothes that cover shoulders and knees","Comfortable sports shoes"],"answer":1,"explanation":"\"Wear clothes that cover your shoulders and knees.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
