    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to Lucía","instructions":"On Tuesday, Lucía leaves you a voice message. Listen and answer the questions.","prompt_text":"Hi, it's Lucía. Quick message about Thursday. Unfortunately our flight to Tashkent has been changed, so we'll only land at seven fifteen that morning, which is far too tight for the eight o'clock train. Is there a later option? We'd really hate to miss Registan, so if something has to go, maybe drop the bazaar. Oh, and I forgot to mention, Marco is vegetarian, so the plov might be a problem.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Why might the guests miss the morning train?","options":["Their flight now lands too late","They lost their passports","The train was cancelled"],"answer":0,"explanation":"\"We'll only land at seven fifteen that morning, which is far too tight for the eight o'clock train.\""},{"id":"q2","prompt":"What would Lucía prefer to drop?","options":["Registan","The bazaar","The dinner meeting"],"answer":1,"explanation":"\"If something has to go, maybe drop the bazaar.\""},{"id":"q3","prompt":"What does she say about Marco?","options":["He doesn't eat meat","He is allergic to rice","He doesn't like spicy food"],"answer":0,"explanation":"\"Marco is vegetarian.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
