    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Send a revised plan","instructions":"Write to Lucía with a revised plan: solve the travel-time problem, explain what you've changed in the programme, and say how you've dealt with Marco's diet.","prompt_text":"To: Lucía\nSubject: Re: Thursday in Samarkand","expected_answer_json":{"goal":"Propose a workable new plan that respects the guests' priorities.","points":[{"label":"solve the travel problem","any":["later train","next train","car","driver","drive","pick you up","collect you","airport"]},{"label":"explain the change to the programme","any":["bazaar","skip","drop*","cancel*","shorten*","instead","moved"]},{"label":"deal with the diet","any":["vegetarian","meat","vegetable*","menu","dish*"]},{"label":"confirm Registan is kept","any":["registan","keep","still"]}],"model_answer":"Dear Lucía,\nThank you for letting me know, and no problem at all. I've booked you both on the 9:30 fast train instead, and our driver will pick you up at the airport and take you straight to the station. We'll still have a full guided visit of Registan, starting at 12:15. To make up the time, we'll skip the bazaar and have a later lunch. I've spoken to the restaurant, and they will prepare a vegetarian menu for Marco. The rest of the day stays the same.\nBest wishes,\nMalika"},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
