    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the HR policy","instructions":"Read the summary of the company's flexible working policy. Then answer the questions.","prompt_text":"Flexible Working Policy (summary)\n• Any employee with at least six months' service may request flexible hours.\n• Requests must be made in writing to your line manager, explaining the proposed schedule and how your work will be covered.\n• Core hours (10:00–16:00) must be worked by all staff unless agreed otherwise with HR.\n• Managers must reply within 14 days. A trial period of up to three months may be agreed before a permanent change.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Who can request flexible hours?","options":["Only managers","Anyone who has worked there for at least six months","Only part-time staff"],"answer":1,"explanation":"\"Any employee with at least six months' service may request flexible hours.\""},{"id":"q2","prompt":"What must a written request include?","options":["A note from your university","The proposed schedule and how your work will be covered","A doctor's letter"],"answer":1,"explanation":"\"Explaining the proposed schedule and how your work will be covered.\""},{"id":"q3","prompt":"What can happen before a permanent change?","options":["A trial period","A pay cut","A meeting with the director"],"answer":0,"explanation":"\"A trial period of up to three months may be agreed before a permanent change.\""}]},"target_skill_key":"reading.detail","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
