    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to your manager","instructions":"You mentioned the course to your manager, Nilufar. She replies with a voice message. Listen and answer the questions.","prompt_text":"Hi, thanks for flagging this. In principle I'm supportive. I know how much the master's means to you. My only worry is Tuesday afternoons. That's when we do the weekly client calls, and they often run until half past five. If you can find a way to cover those, or hand them over to someone, I don't see a problem. Put it in writing and I'll take it to HR.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is the manager's concern?","options":["The cost of the course","The weekly client calls on Tuesday afternoons","Your performance last year"],"answer":1,"explanation":"\"My only worry is Tuesday afternoons. That's when we do the weekly client calls.\""},{"id":"q2","prompt":"What does she ask you to do next?","options":["Talk to HR yourself","Put the request in writing","Change your class days"],"answer":1,"explanation":"\"Put it in writing and I'll take it to HR.\""}]},"target_skill_key":"listening.detail","estimated_minutes":3,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
