    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"writing","step_type":"reply","title":"Write your request","instructions":"Write your formal request to Nilufar. Propose a new schedule for Tuesdays and Thursdays that respects core hours, give the reason, explain how the client calls will be covered, and suggest a trial period.","prompt_text":"To: Nilufar Saidova\nSubject: Flexible working request","expected_answer_json":{"goal":"Make a complete, persuasive request that follows the policy.","points":[{"label":"propose a schedule","any":["8","eight","earlier","4 30","half past four","finish at","leave at","start at"]},{"label":"give the reason","any":["master*","degree","course","classes","stud*","university"]},{"label":"explain how work will be covered","any":["cover*","hand over","handover","colleague","take over","client calls"]},{"label":"suggest a trial","any":["trial","three months","3 months","review"]}],"model_answer":"Dear Nilufar,\nFollowing our conversation, I would like to request a change to my working hours on Tuesdays and Thursdays, so that I can attend my master's classes, which start at 5 pm. On those two days I propose to start at 8:00 and finish at 16:30, so I would still work all core hours. For the Tuesday client calls, Aziz has agreed to take over any call that runs past 16:30, and I will send him a short handover note beforehand. I would be happy to try this for a three-month trial period and review it with you afterwards.\nBest regards,\nTimur"},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
