    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c1-chairing-a-residents-meeting","title":"Chairing a residents' meeting","level":"C1","status":"published","sort_order":200,"metadata":{},"context_text":"You've volunteered to chair a meeting of residents in your apartment building in Tashkent. Several foreign families live there, so meetings are held in English. The question is how to spend this year's shared maintenance fund: modernise the old lift, or renovate the courtyard and playground.","objective_text":"Understand both options and both sides, keep the discussion fair, steer the meeting towards a decision, and communicate the outcome tactfully.","mission_type":"problem_solving","target_vocabulary":["maintenance fund","majority","compromise","concern","set aside"],"target_grammar":"neutral summarising language (What I'm hearing is…; On the one hand…, on the other…)","cultural_note":"A good chair in English-speaking meetings stays visibly neutral: summarising each side fairly before moving to a vote helps people accept a decision they didn't vote for.","success_conditions_json":["Understand the costs and implications of each option and the voting rule","Identify each resident's main argument","Summarise both views neutrally and propose a fair procedure","Announce the result and show how the minority's concerns will be addressed"],"skill_mix":["reading","listening","speaking","writing"]}$seed$::jsonb) r
