    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the proposal summary","instructions":"Read the summary circulated before the meeting. Then answer the questions.","prompt_text":"Maintenance fund: 48 million som available this year.\nOption A: Lift modernisation, 45 million som. The lift is 30 years old and broke down seven times last year. Engineers say it is currently safe, but spare parts are increasingly hard to find.\nOption B: Courtyard and playground, 30 million som for new play equipment, benches and lighting. The remaining 18 million som would be set aside towards lift modernisation next year.\nThe decision requires a simple majority of the households present.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is one financial argument for Option B?","options":["It costs nothing this year","It leaves money set aside for future lift work","It includes a new lift"],"answer":1,"explanation":"\"The remaining 18 million som would be set aside towards lift modernisation next year.\""},{"id":"q2","prompt":"What do the engineers say about the lift?","options":["It is unsafe and must close","It is safe for now, but spare parts are getting harder to find","It must be replaced this month"],"answer":1,"explanation":"\"Engineers say it is currently safe, but spare parts are increasingly hard to find.\""},{"id":"q3","prompt":"How will the decision be made?","options":["Everyone must agree","A simple majority of households present","The chair decides"],"answer":1,"explanation":"\"The decision requires a simple majority of the households present.\""}]},"target_skill_key":"reading.detail","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
