    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to two residents","instructions":"Two residents speak at the meeting. Listen and answer the questions.","prompt_text":"Mrs Usmonova: I live on the ninth floor. When the lift broke down in January, I couldn't leave my flat for three days. A playground is lovely, but this is about people's basic access to their own homes.\nMr Brown: I hear that, and I'm not dismissing it for a second. But the engineers say the lift is safe, and meanwhile our children are playing on broken equipment right now. If we set money aside this year, we can do the lift properly next year instead of rushing it.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is Mrs Usmonova's main argument?","options":["The playground is too expensive","Some residents depend on the lift for basic access","The engineers are wrong"],"answer":1,"explanation":"\"This is about people's basic access to their own homes.\""},{"id":"q2","prompt":"How does Mr Brown respond?","options":["He dismisses her concern","He acknowledges it but argues the playground is more urgent now","He agrees to drop Option B"],"answer":1,"explanation":"\"I'm not dismissing it… meanwhile our children are playing on broken equipment right now.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
