    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"speaking","step_type":"speak","title":"Summarise and move to a decision","instructions":"As chair, summarise both positions neutrally and propose how the meeting should reach a decision.","prompt_text":"Resident: So, chair, where are we? Can we decide now?","expected_answer_json":{"goal":"Give a balanced summary of both views and set out a fair procedure.","points":[{"label":"summarise the case for the lift","any":["lift","access","ninth floor","broke*","breakdown*"]},{"label":"summarise the case for the courtyard","any":["playground","children","kids","equipment","courtyard"]},{"label":"stay neutral","any":["both","on the one hand","on the other hand","valid","fair point*","concerns","understand"]},{"label":"propose a procedure","any":["majority","show of hands","vote","ballot","households","proposal","option a","option b"]}],"model_answer":"Let me summarise. On the one hand, Option A addresses a real access problem: when the lift breaks down, some residents can't leave their homes. On the other hand, Option B fixes equipment the children are using now and sets money aside for the lift next year. Both concerns are clearly valid. I suggest we take a show of hands, one per household, and decide by simple majority."},"target_skill_key":"speaking.task_completion","estimated_minutes":4,"status":"published","metadata":{}}$seed$::jsonb) r;
