    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"writing","step_type":"reply","title":"Announce the result","instructions":"The meeting voted 23 to 17 for Option B, and agreed that the lift will be inspected every month. Write the announcement for the residents' group chat, for people who couldn't attend. Show that the concerns of the other side were heard.","prompt_text":"Residents' group chat\nNeighbour: I couldn't come to the meeting last night. What did we decide?","expected_answer_json":{"goal":"Report the decision clearly and tactfully, addressing the minority's concerns.","points":[{"label":"state the decision","any":["option b","playground","courtyard"]},{"label":"give the vote","any":["23","17","majority","vote*"]},{"label":"address the lift concerns","any":["lift","18","next year","inspect*","monthly","every month","priority"]},{"label":"thank people and keep the tone inclusive","any":["thank*","everyone","respect*","appreciat*"]}],"model_answer":"Hi everyone, here's a summary for those who couldn't make it. After a good discussion, the meeting voted 23 to 17 for Option B: new play equipment, benches and lighting in the courtyard. The remaining 18 million som will be set aside, so the lift modernisation can go ahead next year. We all understood how difficult the January breakdown was for residents on the upper floors, so we also agreed that the lift will be inspected every month until then. Thank you to everyone who came and spoke so respectfully."},"target_skill_key":"writing.task_completion","estimated_minutes":10,"status":"published","metadata":{}}$seed$::jsonb) r;
