    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c1-responding-to-dissertation-feedback","title":"Responding to your supervisor's feedback","level":"C1","status":"published","sort_order":200,"metadata":{},"context_text":"You're writing a master's dissertation at a university abroad on remote work and productivity in small IT companies in Uzbekistan. Your supervisor, Dr Harris, has sent detailed comments on your methodology chapter. You agree with most of them, but you want to keep your online survey.","objective_text":"Interpret the feedback accurately, negotiate your position in a supervision meeting, and confirm the agreed actions in writing.","mission_type":"study","target_vocabulary":["sample","bias","limitation","triangulation","ethical approval"],"target_grammar":"concession and counter-argument (I take the point that…; that said,…)","cultural_note":"In UK and US universities, students are expected to engage critically with supervisors' feedback. Respectfully defending a choice with evidence is welcomed; simply accepting or rejecting every comment is not.","success_conditions_json":["Distinguish the supervisor's major concerns from minor ones","Understand the conditions for keeping the survey","Accept valid criticism and argue your case for the survey","Confirm the agreed actions and a timeline in writing"],"skill_mix":["reading","listening","speaking","writing"]}$seed$::jsonb) r
