    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the supervisor's comments","instructions":"Read Dr Harris's comments on your chapter. Then answer the questions.","prompt_text":"Comments on Chapter 3 (Methodology)\n1. Your sample of 12 interviews is defensible for a qualitative study, but you need to justify it explicitly rather than leave the reader to infer it.\n2. I'm not convinced the online survey adds much. It was answered mainly by your own former classmates, which raises obvious questions about bias. Consider either dropping it or presenting it explicitly as a limitation.\n3. The section on ethics is far too thin. Where is the consent procedure? How did you anonymise the data?\n4. Overall, the chapter reads well. Tighten it and this will be solid.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is the supervisor's view of the 12 interviews?","options":["Too few to be acceptable","Acceptable, but the choice must be justified","They should be replaced by a survey"],"answer":1,"explanation":"\"Your sample of 12 interviews is defensible… but you need to justify it explicitly.\""},{"id":"q2","prompt":"What is the problem with the survey?","options":["It was too long","Its respondents may not be representative","It was not anonymous"],"answer":1,"explanation":"It \"was answered mainly by your own former classmates, which raises obvious questions about bias\"."},{"id":"q3","prompt":"How would you describe the overall tone?","options":["Broadly positive but demanding","Entirely negative","Indifferent"],"answer":0,"explanation":"Point 4 is positive, while points 1–3 ask for significant work."}]},"target_skill_key":"reading.detail","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
