    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to your supervisor","instructions":"In your supervision meeting, Dr Harris explains her position on the survey. Listen and answer the questions.","prompt_text":"Look, I'm open to keeping the survey, but you'd have to make a much stronger case for it. If you can show it tells us something the interviews can't, say, how widespread a pattern is, and you're upfront about who actually answered it, then fine, keep it as a secondary source. What I won't accept is presenting it as if it were representative. And please, sort out the ethics section before anything else. The board won't even look at a submission without it.","expected_answer_json":{"questions":[{"id":"q1","prompt":"Under what conditions can the survey stay?","options":["If more people answer it","If it adds something the interviews can't and its limits are made clear","If it is moved to an appendix"],"answer":1,"explanation":"\"If you can show it tells us something the interviews can't… and you're upfront about who actually answered it.\""},{"id":"q2","prompt":"What is the top priority?","options":["The ethics section","The survey","The interview sample"],"answer":0,"explanation":"\"Please, sort out the ethics section before anything else.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
