    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"speaking","step_type":"speak","title":"Make your case in the meeting","instructions":"Respond to Dr Harris. Accept the points you agree with, and make a reasoned case for keeping the survey while acknowledging its limitations.","prompt_text":"Dr Harris: So, what's your plan for the chapter?","expected_answer_json":{"goal":"Concede valid points and argue persuasively for a qualified use of the survey.","points":[{"label":"accept the ethics point","any":["ethics","ethical","consent","anonymi*"]},{"label":"address the interview sample","any":["sample","twelve","12","justif*","saturation"]},{"label":"argue for the survey","any":["survey","widespread","pattern*","complement*","secondary","triangulat*","breadth"]},{"label":"acknowledge its limitations","any":["limitation*","bias","not representative","upfront","transparent","acknowledge"]}],"model_answer":"First, you're absolutely right about ethics, so I'll rewrite that section this week with the consent procedure and how I anonymised the data. I'll also add a paragraph justifying the sample of twelve. On the survey, I take the point about bias, but I'd like to keep it as a secondary source: it shows how widespread some of the patterns from the interviews are. I'll be transparent that most respondents were former classmates and treat that as a clear limitation."},"target_skill_key":"speaking.task_completion","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"writing","step_type":"reply","title":"Confirm the actions by email","instructions":"After the meeting, email Dr Harris to confirm what you agreed: the actions for each point and when she will receive the revised chapter.","prompt_text":"To: Dr Harris\nSubject: Chapter 3: next steps","expected_answer_json":{"goal":"Record the agreed actions precisely and commit to a timeline.","points":[{"label":"confirm the ethics revision","any":["ethics","ethical","consent","anonymi*"]},{"label":"confirm the decision on the survey","any":["survey","secondary","limitation*","bias"]},{"label":"confirm the sample justification","any":["sample","interviews","justif*","twelve","12"]},{"label":"give a timeline","any":["by","next week","friday","monday","draft","end of the month"]}],"model_answer":"Dear Dr Harris,\nThank you for a very useful meeting today. To confirm what we agreed: first, I will rewrite the ethics section, setting out the consent procedure and how the data were anonymised. Second, I will add an explicit justification for the sample of twelve interviews. Third, I will keep the survey, but only as a secondary source showing how widespread certain patterns are, and I will discuss the bias in its respondents openly as a limitation. I will send you the revised chapter by the end of next week.\nBest wishes,\nDilnoza"},"target_skill_key":"writing.task_completion","estimated_minutes":12,"status":"published","metadata":{}}$seed$::jsonb) r;
