    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.context_text, r.objective_text, r.mission_type, r.target_vocabulary, r.target_grammar, r.cultural_note, r.success_conditions_json, r.skill_mix, v_product_immersion, v_en_id
    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c2-mediating-a-team-conflict","title":"Mediating a conflict between colleagues","level":"C2","status":"published","sort_order":200,"metadata":{},"context_text":"You lead a product team of eight at a software company. Two senior members, Bekzod, the lead developer, and Claire, the product designer, have clashed repeatedly over a checkout redesign, and the tension is now affecting the whole team. You've spoken to each of them privately and arranged a joint conversation.","objective_text":"Read the dynamics behind the conflict, run a fair joint conversation that moves towards a solution, and record what was agreed.","mission_type":"workplace","target_vocabulary":["obstruction","on call","phased rollout","ground rules","reframe"],"target_grammar":"reframing and inclusive language (What I'm hearing from both of you is…; How might we…?)","cultural_note":"In mediation, naming the shared goal and acknowledging both people's pressures before discussing solutions lowers defensiveness. Taking sides, even implicitly, usually entrenches the conflict.","success_conditions_json":["Identify each person's stated position and underlying grievance","Understand what is really at stake for each of them","Open the joint conversation neutrally, with ground rules, a shared goal and a proposal","Record the agreement and the process change accurately and diplomatically"],"skill_mix":["reading","listening","speaking","writing"]}$seed$::jsonb) r
