    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the team chat","instructions":"Read this exchange from the team channel yesterday. Then answer the questions.","prompt_text":"Claire: Users loved the checkout redesign in testing. Can we please ship it this sprint?\nBekzod: As I've said three times now, it breaks the payment flow on older phones. Shipping it now would be reckless.\nClaire: It's been \"three weeks away\" for two months. At some point this starts to look like obstruction.\nBekzod: If you'd involved engineering before the user tests, we wouldn't be here.\nAziz: Could we maybe take this offline?","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is Bekzod's technical concern?","options":["The design hasn't been tested with users","It breaks the payment flow on older phones","It is too expensive to build"],"answer":1,"explanation":"\"It breaks the payment flow on older phones.\""},{"id":"q2","prompt":"What does Claire imply by \"starts to look like obstruction\"?","options":["Bekzod may be delaying the work deliberately","The project lacks resources","Engineering needs more staff"],"answer":0,"explanation":"She suggests the repeated delays may be intentional rather than technical."},{"id":"q3","prompt":"What is Bekzod's underlying grievance?","options":["He dislikes the visual design","Engineering wasn't involved before the user testing","The sprints are too short"],"answer":1,"explanation":"\"If you'd involved engineering before the user tests, we wouldn't be here.\""}]},"target_skill_key":"reading.detail","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the private conversations","instructions":"Listen to extracts from your private conversations with Claire and Bekzod. Then answer the questions.","prompt_text":"Claire: Honestly, I'm exhausted. I've got users asking for this, and every week there's a new reason not to ship. I don't think he respects design as a discipline.\nBekzod: She thinks I'm being difficult. I'm not. About fifteen per cent of our paying customers are on those older phones. If payments fail for them, it's my team who gets called at two in the morning, not hers.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is Claire's deeper frustration?","options":["She feels design is not respected","She feels underpaid","She thinks the users are wrong"],"answer":0,"explanation":"\"I don't think he respects design as a discipline.\""},{"id":"q2","prompt":"What is at stake for Bekzod's team?","options":["Being called out at night if payments fail","Losing their bonus","Having to redesign the checkout"],"answer":0,"explanation":"\"It's my team who gets called at two in the morning, not hers.\""}]},"target_skill_key":"listening.detail","estimated_minutes":4,"status":"published","metadata":{"accent":"us"}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"speaking","step_type":"speak","title":"Open the joint conversation","instructions":"Open the joint conversation. Set ground rules, reframe the dispute around a shared goal, acknowledge both perspectives without taking sides, and put forward a possible way forward.","prompt_text":"Claire and Bekzod sit down, both visibly tense. They look at you.","expected_answer_json":{"goal":"Lower the temperature and steer both colleagues towards a joint solution.","points":[{"label":"set ground rules","any":["ground rules","one at a time","interrupt*","listen","respect*","confidential*"]},{"label":"name the shared goal","any":["both want","shared","same goal","common","customers","users"]},{"label":"acknowledge both perspectives","any":["understand","hear","concern*","pressure","frustrat*","valid"]},{"label":"propose a way forward","any":["propose","suggest","phased","staged","roll out","rollout","what if","could we"]}],"model_answer":"Thank you both for coming. A couple of ground rules: one person speaks at a time, and we listen to understand rather than to reply. As I see it, you both want the same thing, a checkout that customers love and that actually works for all of them. Claire, I hear the frustration of having a validated design stuck for months. Bekzod, I hear the pressure of being the one who's called at two in the morning. So what if we looked at a phased rollout: newer devices first, and older phones once the payment issue is fixed?"},"target_skill_key":"speaking.task_completion","estimated_minutes":6,"status":"published","metadata":{}}$seed$::jsonb) r;
