    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"writing","step_type":"reply","title":"Record the agreement","instructions":"Email both of them to record what was agreed: a phased release (newer devices in the next sprint, older phones once the payment fix is tested), a review date, and earlier engineering involvement in future design work. Keep the tone appreciative and neutral.","prompt_text":"To: Claire, Bekzod\nSubject: Today's conversation","expected_answer_json":{"goal":"Record the agreement precisely and in a way that both parties will accept as fair.","points":[{"label":"record the phased release","any":["phase*","staged","gradual*","newer","older phones"]},{"label":"give the timing","any":["next sprint","sprint","date","deadline","by"]},{"label":"record the process change","any":["involve*","earlier","early","before user test*","from the start","outset","kick off"]},{"label":"express appreciation","any":["thank*","appreciat*","candour","candor","openness","constructive"]},{"label":"set a review","any":["review","check in","follow up","catch up","revisit"]}],"model_answer":"Dear Claire and Bekzod,\nThank you both for such a candid and constructive conversation today. To confirm what we agreed: the redesigned checkout will be released in phases. It will go live for newer devices in the next sprint, and older phones will follow once Bekzod's team has fixed and tested the payment issue, which we expect to take no more than two sprints. For future projects, engineering will be involved from the start of the design process, before any user testing, so that technical risks surface early. I suggest the three of us review progress together in two weeks.\nBest regards,\nNodira"},"target_skill_key":"writing.task_completion","estimated_minutes":14,"status":"published","metadata":{}}$seed$::jsonb) r;
