  else
    insert into public.immersion_missions (slug, title, level, status, sort_order, metadata, context_text, objective_text, mission_type, target_vocabulary, target_grammar, cultural_note, success_conditions_json, skill_mix, product_id, language_id)
    select r.slug, r.title, r.level, r.status, r.sort_order, r.metadata, r.context_text, r.objective_text, r.mission_type, r.target_vocabulary, r.target_grammar, r.cultural_note, r.success_conditions_json, r.skill_mix, v_product_immersion, v_en_id
    from jsonb_populate_record(null::public.immersion_missions, $seed${"slug":"c2-negotiating-a-contract-clause","title":"Negotiating an intellectual property clause","level":"C2","status":"published","sort_order":200,"metadata":{},"context_text":"Your Tashkent-based software company is about to sign a two-year development contract with a client in the UK. Their draft includes an intellectual property clause your CEO considers unacceptable. You're leading the negotiation with the client's lawyer, Ms Fletcher.","objective_text":"Pin down exactly what the clause does, read the other side's underlying interest, respond constructively but firmly, and set out the compromise in precise written terms.","mission_type":"workplace","target_vocabulary":["vest in","pre-existing IP","perpetual licence","royalty-free","escrow"],"target_grammar":"conditional and qualifying structures (provided that…, save that…, subject to…)","cultural_note":"In UK commercial negotiations, positions are often softened with understatement (\"we could live with…\", \"that may be a little broad\"). Reading these signals accurately, and answering in kind, matters as much as the legal substance.","success_conditions_json":["Explain precisely why the clause is unacceptable and what compromise your CEO would accept","Identify the client's underlying interest and the conditions attached to their offer","Accept common ground while qualifying at least one term, keeping the tone constructive","Summarise the proposed revision in precise, unambiguous written language"],"skill_mix":["reading","listening","speaking","writing"]}$seed$::jsonb) r
    returning id into v_parent_id;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":0,"service_key":"reading","step_type":"read","title":"Read the clause and your CEO's note","instructions":"Read the draft clause and your CEO's note on it. Then answer the questions.","prompt_text":"Clause 9.2: Intellectual Property\nAll intellectual property created by the Supplier in the course of, or in connection with, this Agreement, including any pre-existing tools, libraries or know-how incorporated into the Deliverables, shall vest in the Client absolutely upon creation, without further consideration.\n\nCEO's note: \"In connection with\" plus \"including pre-existing tools\" would hand them our in-house framework, which we use for every client. Non-negotiable. A licence, yes; ownership, no.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is the CEO's chief objection?","options":["The client would own the company's existing framework","The contract period is too long","Payment terms are missing"],"answer":0,"explanation":"The clause covers \"pre-existing tools\", which \"would hand them our in-house framework\"."},{"id":"q2","prompt":"What does \"shall vest in the Client absolutely upon creation\" mean?","options":["The client receives a licence once it has paid","Full ownership passes to the client as soon as the work is created","The supplier keeps ownership until the contract ends"],"answer":1,"explanation":"To \"vest absolutely upon creation\" means full ownership transfers at the moment the work exists."},{"id":"q3","prompt":"What compromise does the CEO's note point to?","options":["Granting the client a licence to the pre-existing tools","Removing every IP term from the contract","Selling the framework to the client"],"answer":0,"explanation":"\"A licence, yes; ownership, no.\""}]},"target_skill_key":"reading.detail","estimated_minutes":6,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":1,"service_key":"listening","step_type":"listen","title":"Listen to the client's lawyer","instructions":"On a video call, Ms Fletcher responds to your objection. Listen and answer the questions.","prompt_text":"We understand the concern, but do put yourselves in our position. If we don't own the code outright, we're exposed if we ever change supplier: we'd have paid for software we can't fully control. What we could live with is outright ownership of everything bespoke, plus a perpetual, royalty-free licence to whatever pre-existing components are embedded in it, provided that licence is irrevocable and survives termination. And we'd want the source code held in escrow.","expected_answer_json":{"questions":[{"id":"q1","prompt":"What is the client's underlying worry?","options":["Losing control of the software if they change supplier","The overall price being too high","The supplier's security standards"],"answer":0,"explanation":"\"We're exposed if we ever change supplier: we'd have paid for software we can't fully control.\""},{"id":"q2","prompt":"Which condition does she attach to the licence?","options":["It must be irrevocable and survive termination","It must be renewed every year","It must exclude the source code"],"answer":0,"explanation":"\"Provided that licence is irrevocable and survives termination.\""},{"id":"q3","prompt":"What does \"we could live with\" signal?","options":["Grudging rejection","A workable concession, not an ideal outcome","Enthusiastic agreement"],"answer":1,"explanation":"It is understatement: an acceptable compromise rather than their preferred position."}]},"target_skill_key":"listening.detail","estimated_minutes":5,"status":"published","metadata":{"accent":"gb"}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":2,"service_key":"speaking","step_type":"speak","title":"Respond in the negotiation","instructions":"Respond to Ms Fletcher. Welcome the movement, accept what you can, and qualify at least one element (for example, the scope of the licence or the conditions for releasing the code from escrow). Keep the tone constructive.","prompt_text":"Ms Fletcher: So, does that work for you?","expected_answer_json":{"goal":"Lock in common ground while firmly qualifying at least one term.","points":[{"label":"acknowledge the movement","any":["appreciate","helpful","welcome","constructive","progress","common ground","understand"]},{"label":"accept the core structure","any":["bespoke","licence","license","royalty free","perpetual","irrevocable"]},{"label":"qualify a term","any":["escrow","release","trigger*","insolven*","provided that","as long as","subject to","non exclusive","limited to","scope"]},{"label":"propose a next step","any":["redraft","draft","wording","send","revised","propose"]}],"model_answer":"I appreciate that, and I think we're very close. We're comfortable with you owning everything bespoke outright, and with a perpetual, royalty-free licence to the embedded framework components. Two qualifications, though: the licence would need to be non-exclusive and limited to use within these deliverables, and the source code would only be released from escrow on clearly defined triggers, such as our insolvency. If that works for you, I'll send revised wording tomorrow."},"target_skill_key":"speaking.task_completion","estimated_minutes":5,"status":"published","metadata":{}}$seed$::jsonb) r;
      insert into public.immersion_mission_steps (step_index, service_key, step_type, title, instructions, prompt_text, expected_answer_json, target_skill_key, estimated_minutes, status, metadata, mission_id)
    select r.step_index, r.service_key, r.step_type, r.title, r.instructions, r.prompt_text, r.expected_answer_json, r.target_skill_key, r.estimated_minutes, r.status, r.metadata, v_parent_id
    from jsonb_populate_record(null::public.immersion_mission_steps, $seed${"step_index":3,"service_key":"writing","step_type":"reply","title":"Set out the revised clause","instructions":"Email Ms Fletcher summarising the proposed revision of Clause 9.2 and the conditions you have agreed, in clear and precise language.","prompt_text":"To: Ms Fletcher\nSubject: Clause 9.2: proposed revision","expected_answer_json":{"goal":"Express the compromise precisely enough to be turned straight into contract wording.","points":[{"label":"define what the client owns","any":["bespoke","developed specifically","created specifically","custom"]},{"label":"define the licence","any":["licence","license","royalty free","perpetual","irrevocable","non exclusive"]},{"label":"confirm the supplier retains its existing IP","any":["retain*","remain*","pre existing","framework","background"]},{"label":"set out the escrow terms","any":["escrow","release","insolven*","cease*","trigger*"]}],"model_answer":"Dear Ms Fletcher,\nThank you for a productive discussion. As agreed in principle, we propose the following revision of Clause 9.2. First, all intellectual property in work developed specifically for the Client under this Agreement shall vest in the Client upon payment. Second, the Supplier shall retain ownership of its pre-existing framework, libraries and know-how. Third, the Supplier grants the Client a perpetual, irrevocable, royalty-free and non-exclusive licence to use those pre-existing components solely as embedded in the Deliverables, and this licence shall survive termination. Finally, the source code shall be held in escrow and released to the Client only if the Supplier becomes insolvent or ceases to support the Deliverables. Our counsel will send formal wording by Friday.\nKind regards,\nJasur Karimov"},"target_skill_key":"writing.task_completion","estimated_minutes":14,"status":"published","metadata":{}}$seed$::jsonb) r;
